// Acme design task class 5 (design doc 9 §10.3; BACKLOG item 34): a
// read-only incident review on prod_sim. Everything the investigator sees
// comes through the read broker: logs and replica rows, the customers'
// names, phones and emails masked before any model sees them. Nothing is
// written. Run it with `mandate run … --mode read_only`.

mandate @ 0.3

module acme.tasks.incident @ 0.1

use std.{data, model}
use acme.system.{prod_sim, LogLine, EventRow}

capability Reads    = data.read(prod_sim, mcp_errors, core_warnings, shipment_events, shipment_overview)
capability ModelStd = model.infer(tier: standard)

type Incident = { since: Text, tracking_no: Text }

// A shipment as the investigator may see it: the customer's fields masked.
type ShipmentSeen = {
  tracking_no: Text, status: Text, destination_city: Text, delivery_date: Text,
  delivery_status: Text, attempts: Int, full_name: Masked, phone: Masked, email: Masked
}

type Report = { root_cause: Text, evidence: List<Text>, affected_cities: List<Text> }

agent Investigator {
  role   "Finds the root cause of an incident from logs and replica rows. Changes nothing."
  caps   ModelStd
  budget { tokens: 400k, spend: 2 USD, steps: 6 }
  skill analyze(errors: Untrusted<List<LogLine>>, warnings: Untrusted<List<LogLine>>, events: Untrusted<List<EventRow>>, shipment: Untrusted<List<ShipmentSeen>>) -> Inferred<Report> ! {Model}
}

workflow Investigate(incident: Incident) -> Inferred<Report>
  caps    Reads, ModelStd
  budget  { spend: 3 USD }
{
  let errors   = data.read(prod_sim.mcp_errors, since: incident.since, max_class: secret)
  let warnings = data.read(prod_sim.core_warnings, since: incident.since, max_class: internal)
  let events   = data.read(prod_sim.shipment_events, tracking_no: incident.tracking_no, max_class: internal)
  let shipment = data.read(prod_sim.shipment_overview, tracking_no: incident.tracking_no, max_class: internal)
  delegate Investigator.analyze(errors, warnings, events, shipment)
}

debd98fbb578851f.text:
// A change set over Acme (design doc 9 §3; BACKLOG item 32): a verified plan,
// one verified change per component, landed as one set in the order the
// interface graph asks for: auth and core provide what mcp consumes.

mandate @ 0.4
module acme.tasks.land @ 0.1
use std.{component, git}
use acme.system.{auth, mcp, core, TokenIssuance, CoreApi}

capability Repos = component.repo(auth, mcp, core)

role auditor "A role"
role architect "Architect"

component billing {
  repo     "acme/billing"
  root     "/work/acme-billing"
  lang     ts
  owner    role "architect"
}

environment qa {
  class internal
  authorize deploy by human(role: "auditor")
}

type Plan = { summary: Text }
type Change = { files: List<Text> }

contract PlanAccepted(plan: Plan) {
  accept summarized "The plan says what changes" by static len(plan.summary) >= 1
}

contract ChangeAccepted(change: Change) {
  accept listed "The change names its files" by static len(change.files) >= 1
}

workflow Land(task: Text) -> Text
  caps Repos
{
  let plan = verify Plan { summary: task } against PlanAccepted(Plan { summary: task })
  let a = verify Change { files: ["src/token.ts"] } against ChangeAccepted(Change { files: ["src/token.ts"] })
  let c = verify Change { files: ["src/main/java/Api.java"] } against ChangeAccepted(Change { files: ["src/main/java/Api.java"] })
  let m = verify Change { files: ["src/tools.ts"] } against ChangeAccepted(Change { files: ["src/tools.ts"] })
  let landed = changeset(plan) {
    member auth = git.merge(a)
    member core = git.merge(c)
    member mcp = git.merge(m) approved_by role "architect"
    order auth, core, mcp
    change TokenIssuance additive
    change CoreApi additive
    approve role "architect"
  } idempotent_by task
  "landed"
}

